class Solution {
public:
    int widthOfBinaryTree(TreeNode* root) {
        if (!root) return 0;
        unsigned long long maxWidth = 0;
        vector<pair<TreeNode*, unsigned long long>> q = {{root, 0}};
        while (!q.empty()) {
            unsigned long long firstIdx = q.front().second;
            unsigned long long lastIdx = q.back().second;
            maxWidth = max(maxWidth, lastIdx - firstIdx + 1);
            vector<pair<TreeNode*, unsigned long long>> next_q;
            for (auto& item : q) {
                TreeNode* node = item.first;
                unsigned long long normIdx = item.second - firstIdx;
                if (node->left) next_q.push_back({node->left, 2 * normIdx});
                if (node->right) next_q.push_back({node->right, 2 * normIdx + 1});
            }
            q = next_q;
        }
        return (int)maxWidth;
    }
};

class Solution {
    static class Item {
        TreeNode node;
        long idx;
        Item(TreeNode node, long idx) {
            this.node = node;
            this.idx = idx;
        }
    }

    public int widthOfBinaryTree(TreeNode root) {
        if (root == null) return 0;
        long maxWidth = 0;
        Queue<Item> queue = new LinkedList<>();
        queue.offer(new Item(root, 0L));
        while (!queue.isEmpty()) {
            int size = queue.size();
            long firstIdx = 0, lastIdx = 0;
            for (int i = 0; i < size; i++) {
                Item item = queue.poll();
                TreeNode node = item.node;
                long idx = item.idx;
                if (i == 0) firstIdx = idx;
                if (i == size - 1) lastIdx = idx;
                long normIdx = idx - firstIdx;
                if (node.left != null) queue.offer(new Item(node.left, 2 * normIdx));
                if (node.right != null) queue.offer(new Item(node.right, 2 * normIdx + 1));
            }
            maxWidth = Math.max(maxWidth, lastIdx - firstIdx + 1);
        }
        return (int) maxWidth;
    }
}

var widthOfBinaryTree = function(root) {
    if (!root) return 0;
    let maxWidth = 0n;
    let queue = [{ node: root, idx: 0n }];
    while (queue.length > 0) {
        const count = queue.length;
        const firstIdx = queue[0].idx;
        const lastIdx = queue[count - 1].idx;
        const width = lastIdx - firstIdx + 1n;
        if (width > maxWidth) maxWidth = width;
        const nextQueue = [];
        for (let i = 0; i < count; i++) {
            const { node, idx } = queue[i];
            const normIdx = idx - firstIdx;
            if (node.left) nextQueue.push({ node: node.left, idx: 2n * normIdx });
            if (node.right) nextQueue.push({ node: node.right, idx: 2n * normIdx + 1n });
        }
        queue = nextQueue;
    }
    return Number(maxWidth);
